begin;

select extensions.no_plan();

-- Synthetic-only P6-04 graph. No browser policies exist.
insert into public.organizations (id, legal_name, business_name, slug) values
  ('b8200000-0000-0000-0000-000000000001','P604 Synthetic A Inc.','P604 A','p604-a'),
  ('b8200000-0000-0000-0000-000000000002','P604 Synthetic B Inc.','P604 B','p604-b');
insert into public.branches (id, organization_id, name, slug, code, address_line1, city, province) values
  ('b8300000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','P604 A Main','p604-a-main','P604-A','1 Synthetic St','Test City','Test Province'),
  ('b8300000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','P604 B Main','p604-b-main','P604-B','2 Synthetic St','Test City','Test Province');
insert into public.patients (id, organization_id, patient_number, first_name, last_name, birth_date, preferred_branch_id) values
  ('b8500000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','P604-A-0001','Patient','A',date '1990-01-01','b8300000-0000-0000-0000-000000000001'),
  ('b8500000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','P604-B-0001','Patient','B',date '1991-01-01','b8300000-0000-0000-0000-000000000002');
insert into public.providers (id, organization_id, first_name, last_name, provider_type) values
  ('c2100000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','Dentist','A','REGULAR'),
  ('c2100000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','Dentist','B','REGULAR');
insert into public.procedures (id, organization_id, code, name, default_duration_minutes) values
  ('c3100000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','P604_A','P604 Procedure A',30),
  ('c3100000-0000-0000-0000-000000000002','b8200000-0000-0000-0000-000000000002','P604_B','P604 Procedure B',30);
insert into public.branch_resources (id, organization_id, branch_id, resource_type_id, name) values
  ('c1100000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001',(select id from public.resource_types where code='DENTAL_CHAIR'),'Chair 1');

select extensions.columns_are('public','appointments',array['id','organization_id','branch_id','patient_id','procedure_id','title','starts_at','ends_at','scheduling_status','confirmation_status','encounter_status','booking_channel_code','chief_complaint','internal_scheduling_notes','patient_visible_notes','created_by','version','created_at','updated_at','cancelled_at','completed_at'],'appointments has only the approved P6-04 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.appointments'::regclass),'appointments has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.appointments',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no appointments privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='appointments'),0,'appointments is deny-by-default with no browser policies');
select extensions.lives_ok($$insert into public.appointments (id,organization_id,branch_id,patient_id,starts_at,ends_at) values ('c4100000-0000-0000-0000-000000000001','b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','2026-01-05 09:00:00+00','2026-01-05 09:30:00+00')$$,'an appointment accepts a valid interval without a provider');
select extensions.is((select scheduling_status from public.appointments where id='c4100000-0000-0000-0000-000000000001'),'REQUESTED','appointments default scheduling status to REQUESTED');
select extensions.is((select encounter_status from public.appointments where id='c4100000-0000-0000-0000-000000000001'),'PENDING','appointments default encounter status to PENDING');
select extensions.lives_ok($$insert into public.appointments (organization_id,branch_id,patient_id,procedure_id,scheduling_status,confirmation_status,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','c3100000-0000-0000-0000-000000000001','AWAITING_SPECIALIST','CONFIRMED','2026-01-05 10:00:00+00','2026-01-05 10:30:00+00')$$,'an appointment can exist while awaiting a specialist with an organization procedure');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000002','b8500000-0000-0000-0000-000000000001','2026-01-05 11:00:00+00','2026-01-05 11:30:00+00')$$,'23503',null,'an appointment cannot reference a foreign branch through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000002','2026-01-05 12:00:00+00','2026-01-05 12:30:00+00')$$,'23503',null,'an appointment cannot reference a foreign patient through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,procedure_id,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','c3100000-0000-0000-0000-000000000002','2026-01-05 13:00:00+00','2026-01-05 13:30:00+00')$$,'23503',null,'an appointment cannot reference a foreign procedure through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','2026-01-05 14:00:00+00','2026-01-05 13:30:00+00')$$,'23514',null,'appointments require ends_at after starts_at');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,scheduling_status,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','WAITING','2026-01-05 09:00:00+00','2026-01-05 10:00:00+00')$$,'23514',null,'invented scheduling statuses are rejected');
select extensions.throws_ok($$insert into public.appointments (organization_id,branch_id,patient_id,scheduling_status,starts_at,ends_at) values ('b8200000-0000-0000-0000-000000000001','b8300000-0000-0000-0000-000000000001','b8500000-0000-0000-0000-000000000001','CANCELLED','2026-01-05 15:00:00+00','2026-01-05 15:30:00+00')$$,'23514',null,'a cancelled scheduling status requires a cancellation timestamp');

select extensions.columns_are('public','appointment_providers',array['id','organization_id','appointment_id','provider_id','provider_role','assignment_status','created_at'],'appointment_providers has only the approved P6-04 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.appointment_providers'::regclass),'appointment_providers has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.appointment_providers',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no appointment_providers privileges');
select extensions.lives_ok($$insert into public.appointment_providers (organization_id,appointment_id,provider_id,provider_role) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','PRIMARY_DENTIST')$$,'an appointment provider assignment accepts a valid role');
select extensions.throws_ok($$insert into public.appointment_providers (organization_id,appointment_id,provider_id,provider_role) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000002','PRIMARY_DENTIST')$$,'23503',null,'an appointment cannot reference a foreign provider through the tenant-safe composite foreign key');
select extensions.throws_ok($$insert into public.appointment_providers (organization_id,appointment_id,provider_id,provider_role) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','c2100000-0000-0000-0000-000000000001','PRIMARY_DENTIST')$$,'23505',null,'duplicate provider+role assignments are rejected');

select extensions.columns_are('public','appointment_resources',array['id','organization_id','appointment_id','resource_id','purpose','created_at'],'appointment_resources has only the approved P6-04 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.appointment_resources'::regclass),'appointment_resources has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.appointment_resources',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no appointment_resources privileges');
select extensions.lives_ok($$insert into public.appointment_resources (organization_id,appointment_id,resource_id,purpose) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','c1100000-0000-0000-0000-000000000001','chair')$$,'an appointment resource assignment accepts a valid resource');
select extensions.throws_ok($$insert into public.appointment_resources (organization_id,appointment_id,resource_id,purpose) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','c1100000-0000-0000-0000-000000000001','chair')$$,'23505',null,'duplicate resource assignments are rejected');

select extensions.columns_are('public','appointment_status_history',array['id','organization_id','appointment_id','status_dimension','old_value','new_value','changed_by','changed_at','reason'],'appointment_status_history has only the approved P6-04 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.appointment_status_history'::regclass),'appointment_status_history has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.appointment_status_history',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no appointment_status_history privileges');
select extensions.lives_ok($$insert into public.appointment_status_history (organization_id,appointment_id,status_dimension,old_value,new_value,reason) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','scheduling_status','REQUESTED','SCHEDULED','walk-in')$$,'a status history entry accepts a valid dimension');
select extensions.throws_ok($$insert into public.appointment_status_history (organization_id,appointment_id,status_dimension,old_value,new_value) values ('b8200000-0000-0000-0000-000000000001','c4100000-0000-0000-0000-000000000001','status','REQUESTED','SCHEDULED')$$,'23514',null,'invented status dimensions are rejected');

with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$')
select case when count(*)=0 then 'P1_TEST_PASS' else string_agg(finish,E'\n') end as p1_test_result from test_failures;

rollback;